    tip: 'Халь описывает внешний вид или состояние. Задавай к нему вопрос «В каком состоянии?» или «Как?».\n\nإعراب (جَاءَ زَيْدٌ رَاكِبًا):\nرَاكِبًا: حالٌ منصوبٌ، وعلامةُ نصبِهِ الفتحةُ الظاهرةُ على آخره.'
