    tip: 'Дополнение причины отвечает на вопрос «почему / ради чего?», а дополнение сопровождения стоит после واو المَعِيَّة (в значении «вместе с»).\n\nإعراب (قَامَ زَيْدٌ إِجْلَالًا):\nإِجْلَالًا: مفعولٌ لأجلِهِ منصوبٌ، وعلامةُ نصبِهِ الفتحةُ الظاهرةُ على آخره.'
