    arabicText: 'بَابُ الْمَخْفُوضَاتِ مِنَ الْأَسْمَاءِ\nالمَخْفُوضَاتُ ثَلَاثَةُ أَنْوَاعٍ: مَخْفُوضٌ بِالْحَرْفِ، وَمَخْفُوضٌ بِالْإِضَافَةِ، وَتَابِعٌ لِلْمَخْفُوضِ .\nفَأَمَّا المَخْفُوضُ بِالْحَرْفِ فَهُوَ مَا يُخْفَضُ بِمِنْ، وَإِلَى، وَعَنْ، وَعَلَى، وَفِي، وَرُبَّ، وَالْبَاءِ، وَالْكَافِ، وَاللَّامِ، وَبِحُرُوفِ الْقَسَمِ، وَهِيَ الْوَاوُ، وَالْبَاءُ، وَالتَّاءُ، وَبِوَاوِ رُبَّ، وَبِمُذْ، وَمُنْذُ.\nوَأَمَّا مَا يُخْفَضُ بِالْإِضَافَةِ، فَنَحْوَ قَوْلِكَ: (غُلَامُ زَيْدٍ) وَهُوَ عَلَى قِسْمَيْنِ: مَا يُقَدَّرُ بِاللَّامِ، وَمَا يُقَدَّرُ بِمِنْ، فَالَّذِي يُقَدَّرُ بِاللَّامِ نَحْوَ: (غُلَامُ زَيْدٍ) وَالَّذِي يُقَدَّرُ بِمِنْ، نَحْوَ: (ثَوْبُ خَزٍّ) وَ (بَابُ سَاجٍ) وَ (خَاتَمُ حَدِيدٍ) .',
