      { q:'Определи И\'раб عَمْرًا в وَلَيْتَ عَمْرًا شَاخِصٌ:[cite: 1]', opts:['خبر ليت مرفوع','اسم ليت منصوب','فاعل'], a:1 },
      { q:'Определи И\'раб زَيْدًا в ظَنَنْتُ زَيْدًا مُنْطَلِقًا:[cite: 1]', opts:['مفعول به أول منصوب','اسم ظن','خبر ظن'], a:0 },
      { q:'Как три группы عوامِل (Кяна, Инна, Занна) меняют المبتدأ и الخبر?[cite: 1]', open:true }
