      { q:'Если слово не является масдаром, можно ли сделать его Маф\'улем мин аджлихи?', opts:['Да','Обычно нет, для вещей и предметов используют предлог Лям (مثال: جئتُ للكتابِ)','Да, через Кяна'], a:1 },
      { q:'Какое главное слово в определении показывает его суть?', opts:['الزمان','السَبَب (Причина)','المكان'], a:1 },
      { q:'Что такое المَفْعُولُ مِنْ أَجْلِهِ и на какой вопрос он отвечает?', open:true }
