let LESSON_ID = null;

function openLesson(partId) {
  LESSON_ID = partId;
  navigate('s-lesson');
}

let PRACTICE_ID = null;
let PR_ANSWERS = {};
let PR_CHECKED = false;

function openPractice(id) {
  PRACTICE_ID = id;
  PR_ANSWERS = {};
  PR_CHECKED = false;
  navigate('s-practice');
}

function renderPractice() {
  const p = PRACTICE[PRACTICE_ID];
  if (!p) {
    $('#practice-body').innerHTML = `<div class="empty-state"><div class="es-title">Скоро</div></div>`;
    $('#practice-title').textContent = 'Практика';
    return;
  }
  $('#practice-title').textContent = p.title;

  const closed = p.items.filter(i => !i.open);
  let html = '';

  // Результат после проверки
  if (PR_CHECKED) {
    let ok = 0;
    p.items.forEach((it, i) => { if (!it.open && PR_ANSWERS[i] === it.a) ok++; });
    const pct = closed.length ? Math.round(ok / closed.length * 100) : 0;
    html += `<div class="pr-result" style="margin-top:16px">
      <div class="pr-result-n">${pct}%</div>
      <div class="pr-result-l">${ok} из ${closed.length} верно</div>
    </div>`;
  } else {
    html += `<div style="height:16px"></div>`;
  }

  // Вопросы
  p.items.forEach((it, i) => {
    html += `<div class="pr-q">
      <div class="pr-q-num">Вопрос ${i + 1}</div>
      <div class="pr-q-text">${esc(it.q)}</div>`;

    if (it.ar) html += `<div class="pr-q-ar">${esc(it.ar)}</div>`;

    if (it.open) {
      html += `<div class="pr-open">Открытый вопрос — ответь себе сам, сверься с таблицей урока.</div>`;
    } else {
      html += `<div class="pr-opts">`;
      it.opts.forEach((o, oi) => {
        let cls = 'pr-opt';
        if (PR_CHECKED) {
          if (oi === it.a) cls += ' ok';
          else if (PR_ANSWERS[i] === oi) cls += ' bad';
        } else if (PR_ANSWERS[i] === oi) {
          cls += ' sel';
        }
        html += `<button type="button" class="${cls}" data-act="pr-pick" data-qi="${i}" data-oi="${oi}">${esc(o)}</button>`;
      });
      html += `</div>`;
    }
    html += `</div>`;
  });

  // Кнопка проверки / сброса
  if (!PR_CHECKED) {
    const allAnswered = p.items.every((it, i) => it.open || PR_ANSWERS[i] !== undefined);
    html += `<button type="button" class="btn ${allAnswered ? 'btn-primary' : 'btn-secondary'}" 
      style="margin-top:6px" data-act="pr-check">Проверить</button>`;
    if (!allAnswered) {
      html += `<div class="tiny" style="text-align:center;margin-top:8px">Ответь на все вопросы</div>`;
    }
  } else {
    html += `<button type="button" class="btn btn-secondary" style="margin-top:6px" data-act="pr-reset">Пройти заново</button>`;
  }

  $('#practice-body').innerHTML = html;
}

function renderLesson() {
  const lesson = LESSONS[LESSON_ID];
  console.log("LESSON_ID =", LESSON_ID, lesson?.title);
  if (!lesson) {
    $('#lesson-body').innerHTML = `<div class="empty-state"><div class="es-title">Скоро</div><div class="es-text">Урок в разработке</div></div>`;
    $('#lesson-title').textContent = 'Урок';
    return;
  }
  $('#lesson-title').textContent = lesson.title;
  let html = '';

  // Арабский текст
  html += `<div class="lesson-arabic-text">${esc(lesson.arabicText).replace(/\n/g,'<br>')}</div>`;

  // Объяснение
  html += `<div class="lesson-explain">
    <div class="lesson-explain-title">
      <span style="background:var(--brand-100);color:var(--brand-600);width:22px;height:22px;border-radius:50%;display:grid;place-items:center;font-size:13px;flex-shrink:0">?</span>
      Что такое речь (الكَلام)?
    </div>
    <div class="lesson-explain-text">${esc(lesson.explain)}</div>
  </div>`;

  // Карточки 1/2/3

 if (lesson.cards?.length) {
  html += `<div class="lesson-cards-row">`;

  lesson.cards.forEach(c => {
    html += `<div class="lesson-card">
      <div class="lesson-card-num" style="background:${c.color}">${c.num}</div>
      <div class="lesson-card-ar">${esc(c.ar)}</div>
      <div class="lesson-card-label">${esc(c.label).replace(/\n/g,'<br>')}</div>
    </div>`;
  });

  html += `</div>`;
}



  // Таблица (новый формат)
  if (lesson.table) {
    html += `<table class="lesson-table"><thead><tr>`;
    lesson.table.head.forEach(h => { html += `<th>${esc(h)}</th>`; });
    html += `</tr></thead><tbody>`;
    lesson.table.rows.forEach(r => {
      html += `<tr>`;
      r.forEach(c => { html += `<td>${esc(c)}</td>`; });
      html += `</tr>`;
    });
    html += `</tbody></table>`;
  }

  // Секции (старый формат, если остались)
  (lesson.sections || []).forEach(s => {
    html += `<div class="lesson-section">
      <div class="lesson-section-title" style="color:${s.color}">${esc(s.title)}</div>`;
    (s.bullets || []).forEach(b => {
      html += `<div class="lesson-bullet">${esc(b)}</div>`;
    });
    if (s.example) {
      html += `<div class="lesson-example">
        <div class="ex-ar" style="color:${s.color}">${esc(s.example.ar)}</div>
        <div style="font-size:13px;color:var(--text-3);margin-top:4px">${esc(s.example.ru)}</div>
      </div>`;
    }
    html += `</div>`;
  });

  // Кнопка "Практика" -- показывается один раз, после всех секций
  if (PRACTICE[LESSON_ID]) {
    html += `<button type="button" class="btn btn-primary" style="margin-top:6px" data-act="open-practice">
      <svg viewBox="0 0 24 24"><path d="M9 11l3 3L22 4M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>
      Практика
    </button>`;
  }

  // Совет
  if (lesson.tip) {
    html += `<div class="lesson-tip">
      <div class="lesson-tip-icon">💡</div>
      <div class="lesson-tip-text"><b>Важно запомнить:</b><br>${esc(lesson.tip)}</div>
    </div>`;
  }

  $('#lesson-body').innerHTML = html;
  }

applyTheme(STATE.settings?.theme || 'light');
navigate('s-home', { stack: false });
